const $=s=>document.querySelector(s);
let currentState;const readers=new Map();
function collapseState(){
 const frames=[...document.querySelectorAll('iframe')],pair=frames.map(f=>readers.get(f.contentWindow));
 const completed=currentState?.provider?.experiment;
 const wasDifferent=pair.every(p=>p?.initial)&&pair[0].initial.value!==pair[1].initial.value;
 const bothFresh=pair.every(p=>p?.fresh&&!p.fresh.experiment?.inExperiment);
 const choice=completed?.rollout_decision==='control'?'correction_note':completed?.rollout_decision==='variant'?'evidence_time_machine':null;
 if(completed?.status==='completed'&&wasDifferent&&bothFresh&&choice&&pair.every(p=>p.initial.experiment_id===completed.id&&p.fresh.value===choice)){
  $('#result-title').textContent='FORK COLLAPSED';$('.experiment-status').classList.add('collapsed');$('#collapse-note').textContent=`Both previously different readers now receive ${choice==='correction_note'?'Correction Note':'Evidence Time Machine'} from the same Flagsmith flag.${currentState.environment==='Development'?' Development rehearsal; no human comprehension winner is claimed.':''}`;
 }else if(completed?.status==='completed')$('#collapse-note').textContent='Provider completion is recorded. Refresh both previously assigned readers to verify convergence.';
}
window.addEventListener('message',e=>{if(e.origin!==location.origin||!document.querySelectorAll('iframe').length||![...document.querySelectorAll('iframe')].some(f=>f.contentWindow===e.source))return;const p=readers.get(e.source)||{};if(e.data?.type==='proofpivot-assigned')p.initial=e.data;if(e.data?.type==='proofpivot-reevaluated')p.fresh=e.data;readers.set(e.source,p);collapseState();});
async function refresh(){
 $('#refresh').disabled=true;
 try{
  const r=await fetch('/api/judge-state');if(!r.ok)throw Error('Evidence unavailable');const s=await r.json();
  currentState=s;
  document.querySelector('.judge-intro .pill').textContent='FACTS LOCKED';
  $('#run-label').textContent=`${s.environment} · ${s.mode==='aa'?'A/A calibration — both readers receive identical Correction Notes':'Correction Fork'} · Experiment ${s.experiment_id}`;
  $('#result-title').textContent=({COLLECTING_DATA:'Collecting data.',INCONCLUSIVE:'Inconclusive.',DO_NOT_ACT:'Do not act.',HUMAN_REVIEW_REQUIRED:'Human review required.'})[s.state]||'Evidence pending.';
  $('#result-note').textContent=s.mode==='aa'?'This is a real Development A/A. It validates assignment and event wiring; it does not measure a human comprehension benefit.':'No evidence-backed winner has been declared. Human rollout approval and reconciliation are required.';
  if(s.evidence?.interval)$('#result-note').textContent+=` Provider 95% relative-lift interval: ${(s.evidence.interval[0]*100).toFixed(1)}% to ${(s.evidence.interval[1]*100).toFixed(1)}%.`;
  $('#counts').textContent=JSON.stringify(s.ledger,null,2);
  $('#provider-proof').textContent=s.provider?JSON.stringify(s.provider,null,2):'Provider result snapshot not collected yet. No result is invented.';
  collapseState();
 }catch(e){document.querySelector('.judge-intro .pill').textContent='FACTS UNAVAILABLE';$('#result-title').textContent='Evidence unavailable.';$('#result-note').textContent=e.message;}
 finally{$('#refresh').disabled=false;}
}
$('#refresh').addEventListener('click',refresh);refresh();

